# Standard library
import uuid
from datetime import date, datetime

# Third-party
from geoalchemy2 import Geometry
from sqlalchemy import Boolean, Date, DateTime, Integer, Text, func
from sqlalchemy.orm import Mapped, mapped_column, relationship

# Local application
from app.core.base import Base


class ProfileUsrUser(Base):
    __tablename__ = "profile_usr_user"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        comment=(
            "Timezone-aware UTC timestamp of when the user account was first "
            "created, set automatically on INSERT."
        ),
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
        comment=(
            "Timezone-aware UTC timestamp of the last profile update, kept "
            "current by the moddatetime trigger."
        ),
    )
    email: Mapped[str] = mapped_column(
        Text,
        nullable=False,
        unique=True,
        comment=(
            "Unique email address used for authentication and communication. "
            "Serves as the primary login identifier."
        ),
    )
    username: Mapped[str] = mapped_column(
        Text,
        nullable=False,
        unique=True,
        comment=(
            "Unique public username displayed in the UI and used in profile "
            "URLs. Must be distinct across all users."
        ),
    )
    first_name: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Optional given (first) name of the"
            " user, shown on the profile page."
        ),
    )
    middle_name: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Optional middle name of the user, stored for completeness."
        ),
    )
    last_name: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Optional family (last) name of the"
            " user, shown on the profile page."
        ),
    )
    gender: Mapped[str | None] = mapped_column(
        Text,
        comment=(
            "Self-reported gender of the user."
            " One of 'male', 'female', or"
            " 'not_specified'."
        ),
    )
    birth_date: Mapped[date | None] = mapped_column(
        Date,
        comment=(
            "Date of birth of the user, used"
            " to calculate age-based statistics"
            " and heart-rate zones."
        ),
    )
    height_cm: Mapped[int | None] = mapped_column(
        Integer,
        comment=(
            "Height of the user in centimetres,"
            " used in calorie and pace"
            " calculations."
        ),
    )
    max_heart_rate: Mapped[int | None] = mapped_column(
        Integer,
        comment=(
            "Maximum heart rate in beats per"
            " minute, used to compute training"
            " zones and intensity metrics."
        ),
    )
    resting_heart_rate: Mapped[int | None] = mapped_column(
        Integer,
        comment=(
            "Resting heart rate in beats per"
            " minute, used alongside max HR to"
            " calculate heart-rate reserve."
        ),
    )
    home_location = mapped_column(
        Geometry("POINT", srid=4326),
        nullable=True,
        comment=(
            "Home location of the user as a"
            " PostGIS Point in WGS 84"
            " (SRID 4326), used for proximity"
            " searches and map defaults."
        ),
    )
    is_active: Mapped[bool] = mapped_column(
        Boolean,
        nullable=False,
        server_default="true",
        comment=(
            "Whether the user account is"
            " currently active. Inactive"
            " accounts cannot log in. Defaults"
            " to true on creation, toggled by"
            " admin deactivation."
        ),
    )
    last_active_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        comment=(
            "Timezone-aware UTC timestamp of"
            " the most recent user activity,"
            " updated on each authenticated"
            " request."
        ),
    )
    avatar_photo_id: Mapped[uuid.UUID | None] = mapped_column(
        comment=(
            "FK to asset_agg_photo. Points to"
            " the photo used as the user avatar"
            " in listings and profile views."
        ),
    )

    credentials = relationship(
        "ProfileUserCredentials",
        back_populates="user",
        uselist=False,
        lazy="selectin",
    )

    @property
    def user_group(self) -> str | None:
        # Lets an expanded user show its group like GET /profile/users/me does. The group is stored on the
        # credentials row, which is loaded together with the user (lazy="selectin").
        return self.credentials.user_group if self.credentials else None
